"""Serialize the authored customer relationship design, not vendor payloads."""
import json
import re
from pathlib import Path
RUN = Path(__file__).resolve().parent
def refs(*numbers): return [f'SRC-{n:03d}' for n in numbers]

def build():
    rows = [
        ('TMF629 Customer Management OAS', 'TM Forum', 'https://raw.githubusercontent.com/tmforum-apis/TMF629_CustomerManagement/main/TMF629-Customer_Management-v5.0.1.oas.yaml', '5.0.1; mutable main commit pin pending', 'schema', 'Selected PartyRole, engagedParty, AccountRef and lifecycle examples; full required/discriminator graph not verified.'),
        ('Customer entities: Account and Contact', 'Microsoft', 'https://learn.microsoft.com/en-us/dynamics365/customerengagement/on-premises/developer/customer-entities-account-contact?view=op-9-1', 'On-premises 9.1 documentation; date pin pending', 'first-party-doc', 'Selected CRM account hierarchy and contact distinctions; implementation constraints are not universal legal structure.'),
        ('Dataverse Account table reference', 'Microsoft', 'https://learn.microsoft.com/en-us/power-apps/developer/data-platform/reference/entities/account', 'Mutable reference; exact release pin pending', 'first-party-doc', 'Selected DoNotEMail boolean and permissive default; consent separation is a Vercy inference, not a legal claim.'),
        ('Customer object', 'Stripe', 'https://docs.stripe.com/api/customers/object', 'Mutable API documentation; API release pin pending', 'first-party-doc', 'Selected nullable email and discount fields illustrate scoped billing customer information; not a complete CRM mapping.'),
        ('PROV-O: The PROV Ontology', 'W3C', 'https://www.w3.org/TR/prov-o/', 'Recommendation; exact dated pin pending', 'ontology', 'Selected attribution and derivation concepts for record lineage, not evidence of commercial authority.'),
        ('Date and Time on the Internet: Timestamps', 'IETF', 'https://www.rfc-editor.org/rfc/rfc3339', 'RFC 3339 July 2002', 'standard', 'Selected timestamp grammar and examples; precise instants separate from date-only effects and identifiers.')
    ]
    sources = [dict(id=f'SRC-{i:03d}', title=t, organization=o, url=u, version_or_date=v, source_type=k, primary_source=True, authority_tier=2 if k=='first-party-doc' else 1, accessed_at='2026-09-09T21:10:00Z', relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
    ids=['customer-identity','customer-kind','customer-recognition','customer-state','customer-grouping','customer-responsibility','customer-bindings','customer-contact','customer-assessment','customer-reconciliation','customer-stewardship','customer-mapping']
    citations=[refs(1,2),refs(1,2,4),refs(1,2,5),refs(1,5,6),refs(1,2),refs(1,2,5),refs(1,4),refs(1,3,4),refs(1,2,5),refs(2,5,6),refs(1,3,5),refs(1,2,3,4,5,6)]
    kinds=[['identity','relationship','evidence'],['classification','relationship','authority'],['evidence','process','constraint'],['state','temporal','lifecycle'],['relationship','composition','constraint'],['ownership','authority','process'],['relationship','provenance','constraint'],['relationship','provenance','authority'],['evidence','measurement','privacy'],['identity','decision','exception'],['ownership','access','retention'],['interoperability','quality','validation']]
    bundles=[]; n=0
    for group in re.split(r'(?m)^## ', (RUN/'question-design.md').read_text(encoding='utf-8'))[1:]:
        title=re.sub(r'^\d+\s+', '', group.split('\n',1)[0]); layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            heading,body=section.split('\n',1); name=re.sub(r'^\d+\.\d+\s+','',heading)
            qtext,answertext=body.split('Answer groups:',1)
            questions=re.findall(r'(?m)^\d\. (.+\?)$',qtext)
            groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answertext)
            assert len(questions)==len(groups)==3
            lid=ids[n]; sr=citations[n]
            desc='Customer relationship record for '+name.lower()+', qualified by seller, source and effective scope; not remastered party or billing truth.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed structured answer fields: '+members+'. Explicit unknown and source attribution required when unresolved. Nested executable constraints are deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr) for key,members in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-artifact',name=name+' evidence record',description='Revisioned minimal assertion with authorized evidence references; excludes payment instruments, credentials and unnecessary private contact payloads.',media_or_form=['text/markdown','application/json','application/yaml','external reference'],serial=True,identity_strategy='Master-qualified stable ID, otherwise Dimension UUID; separate immutable revision and digest, never timestamp alone.',source_refs=sr)],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr,findings=[finding])); n+=1
        assert len(layers)==2
        bundles.append(dict(id='customer-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Customer relationship '+title.lower()+'.',rationale='Two complementary customer-owned records; related parties, commercial transactions and service systems remain referenced masters.',source_refs=sorted(set(s for layer in layers for s in layer['source_refs'])),layers=layers))
    assert n==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-org-014',model_id='WM-ORG-014',name='Customer / Account Relationship',entry_kind='relationship',purpose='Describe a customer relationship mastered by CRM, including seller scope, role, lifecycle, commercial references and accountable context.',scope_statement='A source-qualified commercial relationship, not global party identity. CRM account, individual contact, billing customer, login, prospect and entitlement remain distinct record kinds.',in_scope=['Seller-scoped customer identity, participant roles and recognition evidence','Source lifecycle, grouping, account responsibility and contact preference provenance','Commercial-master references, interactions, duplicate lineage and governed exchange'],out_of_scope=['Party identity, login credentials and payment instruments','Executing outreach, charging, credit decisions, service entitlement changes or CRM merge transactions','Universal customer state machine, legal corporate hierarchy or consent inference'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=c) for a,b,c in [('Party master','One party can participate in multiple customer relationships and seller/service scopes.',refs(1,2)),('Billing and subscription masters','Their attributed snapshots and typed references do not define CRM relationship truth.',refs(1,4)),('Lead and opportunity','Customer recognition needs declared evidence; prospect record creation alone is not universal establishment of a relationship.',refs(1,2)),('Contact and communication authority','A contact link or permissive preference default proves neither authority to purchase nor permission to communicate.',refs(1,3))]])
    services=dict(
      dimension=dict(owner_package_requirements=['Identify CRM relationship owner and accountable steward.','Declare party, billing, agreement, consent and support masters.','Bind purpose, access, retention and cross-Dimension disclosure rules.'],namespace_guidance='Customer ID is master-qualified and seller/service-scoped. Never merge identities by email or display name alone.',registry_links=['Customer relationship registry','Party and seller registries','Commercial-master references','Policy and revision registries']),
      canon_and_patch=dict(canonicalization_rules=['Preserve source record kind, scope and lifecycle scheme.','Keep contact preferences, communication authority and commercial authority separate.'],patch_rules=['Use namespaced additive profiles pinned to base version and digest.','Expected-head writes append corrections and lineage; conflicting source claims remain explicit.'],compatibility_rules=['Changed customer kind, hierarchy cardinality or preference semantics require migration and loss report.','Absent flags are not permission; date-only facts are not fabricated instants.']),
      artifact_rules=dict(identity_priority=['Authoritative master-qualified identifier','Governed issuer-qualified URI','Dimension-issued UUID'],timestamp_rule='RFC 3339 with seconds and explicit offset or Z for recording and observation instants; retain date-only or uncertain source effect separately.',serial_naming_rule='Customer record-kind prefix plus escaped stable ID and revision; no private names or emails in filenames.',integrity_rule='Verify exact-byte digest and expected revision. Integrity does not establish commercial truth or contact consent.'),
      policies=['Do not infer consent or authority from contact association, account grouping or permissive defaults.','Keep financial, service and eligibility decisions with their authorized masters.','Minimize personal information; do not infer sensitive traits or unexplained customer worth scores.','Treat duplicate detection as evidence-based proposal; preserve separate seller scopes and correction paths.'],
      crud=dict(read=['Read Dimension purpose, source kind, scope, provenance, validity and assurance before using the record.'],create=['Create only an authorized scoped relationship assertion with explicit unknowns and referenced masters.'],update=['Append authorized evidence and changed source states under expected-head checks; do not mutate billing or messaging systems.'],delete=['Apply approved retention/correction and justified holds; a local tombstone does not cancel contracts, debt or party identity.']),
      roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Defines purpose and delegation.'),('Customer-data steward','Maintains scope, mastership and lifecycle attribution.'),('Contributor','Records authorized minimal evidence.'),('Reviewer','Checks ambiguous identity, grouping, preferences and proposed reconciliation.'),('Custodian','Enforces retention, field disclosure and audit controls.')]],
      access=dict(default_rule='Deny unless purpose-specific access is delegated by the owning Dimension; CRM access does not grant billing or private-party access.',scopes=['bundle','layer','finding','artifact'],exceptions=['Explicit time-limited delegated exceptions must name fields, purpose and approving authority.'],audit_requirements=['Log actor, authorized operation, reference, revision and decision without secrets or private payloads.']),
      agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension policy and relationship mastership','Pinned specification, source record kind and seller scope','Role, lifecycle, references, authority evidence and time','Safe record operations, validation, extension and retention']))
    frows=[
      ('resolve-customer','Resolve customer relationship','Find a scoped relationship, not a global person identity.',['Master-qualified ID or scoped candidates','Authorized seller scope'],['Resolved reference or explicit ambiguity'],['Read permission','No email-only identity inference'],['Read-only resolution; unknown remains unresolved'],refs(1,2,4)),
      ('record-customer-role','Record customer role and scope','Append an attributed participant role.',['Party and seller refs','Role evidence','Expected head'],['New revision or conflict'],['Write delegation','Kind and scope validated'],['Local assertion only; no purchasing or messaging authority created'],refs(1,2,5)),
      ('revise-customer-state','Revise attributed lifecycle','Record a source-state change with effective and knowledge time.',['Source scheme and evidence','Times and precision','Expected head'],['Successor assertion or contested states'],['Source master verified','Write scope'],['Local revision only; no contract, debt or entitlement cancellation'],refs(1,5,6)),
      ('link-customer-masters','Link commercial masters','Associate typed billing, agreement and support references.',['Typed refs','Role and source','Expected head'],['Traceable link or unresolved target'],['Access to permitted reference metadata','Target kind checked'],['Local reference update; no charge, service or case operation'],refs(1,4,5)),
      ('propose-customer-reconciliation','Propose duplicate reconciliation','Prepare a scoped merge/split proposal with recovery lineage.',['Candidate refs','Scope evidence','Revision mapping'],['Proposal with ambiguity and recovery plan'],['Read permission','No automatic identity collapse'],['No CRM merge execution; approval and transaction remain with master'],refs(2,5,6)),
      ('export-customer-projection','Export permitted projection','Map only authorized relationship fields.',['Allowed fields','Pinned target kind/profile','Loss definitions'],['Minimized projection or refusal'],['Disclosure authority','Mapping constraints checked'],['No publication or external transmission without authority; unresolved semantics yield warning/refusal'],refs(1,2,3,4))]
    functions=[dict(id=i,name=n,description=d,inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,d,a,b,c,e,s in frows]
    composition=[dict(target=t,relation=r,purpose=p,required=False,source_refs=s) for t,r,p,s in [('WM-ORG-012','REFERENCE','Proposed inter-organization link for business customers; not an approved hierarchy or universal party master.',refs(1,2)),(rows[0][2],'ALIGN','Candidate TMF629 mapping; full schema conformance is not claimed.',refs(1)),(rows[4][2],'ALIGN','Candidate record attribution and derivation vocabulary.',refs(5))]]
    dimensions=[('identity','Master-qualified relationship, distinct from party.'),('classification','Explicit CRM/customer/contact/billing kind.'),('direct properties','Role, scope and attributed state; no invented physical geometry.'),('recognition','Evidence-based customer definition, not email equality.'),('capabilities','Six scoped record operations, no commerce execution.'),('lifecycle','Source-qualified state and distinct closure meanings.'),('relationships','Participant and commercial references preserve mastership.'),('temporal','Effect, observation and recording precision separated.'),('provenance','Field source and reconciliation lineage retained.'),('ownership','Steward and participant authority are separate.'),('access','Purpose-specific field scopes and disclosure controls.'),('retention','Correction, minimization and justified history.'),('interoperability','Version/kind-specific mappings with loss reporting.')]
    coverage=dict(claim='Bounded proposed customer relationship context contract; not a universal CRM schema, legal decision policy or executed integration.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dimensions]+[dict(dimension='validation',status='gap',notes='Structural validator only; nested runtime constraints, merge recovery, privacy and round-trip fixtures remain to implement.'),dict(dimension='Physical material and geometry',status='not-applicable',notes='Commercial relationship is abstract; physical party/object attributes remain elsewhere.')],known_omissions=['Claude and Grok each timed out once; Codex-only reviewable-draft without independent review.','Selected source clauses only; full required-field graph, exact release/commit pins and licenses unverified.','No executable nested schemas, CRM adapters, consent verifier or merge/round-trip fixtures delivered.','Customer industry/jurisdiction profiles and approved composition ledger edges remain pending.'],conflicts=[],regional_assumptions=['TM Forum, Microsoft and Stripe model different system scopes. No vendor schema is asserted as universal law or permission for contact, credit or billing.'],adversarial_checks=['Same email cannot merge different sellers or parties.','Default allow-email flag is not consent.','CRM grouping does not imply legal control or data-sharing rights.','Closed relationship does not cancel debt or a contract.','Contact link does not grant purchasing authority.','Prospect existence does not universally establish customer status.','Mistaken merge needs compensating lineage, not overwritten evidence.','Payment status is an attributed snapshot, not customer identity.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
